import{_ as a,o as e,c as s,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const b=JSON.parse('{"title":"第 28 章 扩展、定时任务与多端接入","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第五篇 平台能力全景/第 28 章 扩展、定时任务与多端接入.md","filePath":"bluebook/第五篇 平台能力全景/第 28 章 扩展、定时任务与多端接入.md"}'),d={name:"bluebook/第五篇 平台能力全景/第 28 章 扩展、定时任务与多端接入.md"};function n(r,t,l,i,p,h){return e(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-28-章-扩展、定时任务与多端接入" tabindex="-1">第 28 章 扩展、定时任务与多端接入 <a class="header-anchor" href="#第-28-章-扩展、定时任务与多端接入" aria-label="Permalink to &quot;第 28 章 扩展、定时任务与多端接入&quot;">​</a></h1><blockquote><p>本章目标：让&quot;我&quot;从<strong>等你开口</strong>变成<strong>自己开工、自己送件、自己接人</strong>。四件事——定时任务、能力市场、远程访问、外部投递。读完你会知道怎么把一条工作流变成真正的&quot;自动产线&quot;。</p></blockquote><h2 id="_28-1-从-我在这儿等你-到-我自己开工" tabindex="-1">28.1 从&quot;我在这儿等你&quot;到&quot;我自己开工&quot; <a class="header-anchor" href="#_28-1-从-我在这儿等你-到-我自己开工" aria-label="Permalink to &quot;28.1 从&quot;我在这儿等你&quot;到&quot;我自己开工&quot;&quot;">​</a></h2><p>前面所有章节都有一个共同前提：<strong>你先说话。</strong></p><p>但真实业务里，很多活儿是<strong>到点就该干</strong>的：</p><ul><li>每天早上 9 点，汇总昨天的行业新闻</li><li>每周五下午，把本周产出整理成周报</li><li>每月 1 号，拉数据生成经营分析</li></ul><p>你不可能每周五准时想起来&quot;该让它做周报了&quot;。<strong>所以需要让我自己醒来。</strong></p><h2 id="_28-2-定时任务-让我按时开工" tabindex="-1">28.2 定时任务：让我按时开工 <a class="header-anchor" href="#_28-2-定时任务-让我按时开工" aria-label="Permalink to &quot;28.2 定时任务：让我按时开工&quot;">​</a></h2><h3 id="_28-2-1-基本规则" tabindex="-1">28.2.1 基本规则 <a class="header-anchor" href="#_28-2-1-基本规则" aria-label="Permalink to &quot;28.2.1 基本规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><strong>一个会话一个任务</strong></td><td>每个会话最多挂一个定时任务，简单清晰</td></tr><tr><td>时间表达</td><td>用标准 cron 表达式</td></tr><tr><td>工作方式</td><td>到点自动执行你交代的那件事</td></tr><tr><td>管理</td><td>随时查询、修改、停用</td></tr></tbody></table><h3 id="_28-2-2-怎么用-话术模板" tabindex="-1">28.2.2 怎么用（话术模板） <a class="header-anchor" href="#_28-2-2-怎么用-话术模板" aria-label="Permalink to &quot;28.2.2 怎么用（话术模板）&quot;">​</a></h3><p><strong>创建：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每天早上 9 点，帮我抓取 AI 行业的最新动态，整理成 5 条摘要</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周五 17:00，把本周我们在这个会话里产生的产出汇总成一份周报</span></span></code></pre></div><p><strong>查询：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看看我现在的定时任务</span></span></code></pre></div><p><strong>修改：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把那个行业动态的任务改成每天下午 6 点</span></span></code></pre></div><h3 id="_28-2-3-一个关键设计-两步走" tabindex="-1">28.2.3 一个关键设计：两步走 <a class="header-anchor" href="#_28-2-3-一个关键设计-两步走" aria-label="Permalink to &quot;28.2.3 一个关键设计：两步走&quot;">​</a></h3><p>定时任务不是&quot;你说完我就默默建好&quot;，而是走两步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 我先查：这个会话现在有没有定时任务？</span></span>
<span class="line"><span>② 再决定：没有 → 新建；有 → 更新（而不是叠加第二个）</span></span></code></pre></div><p><strong>为什么要这样？</strong> 因为&quot;一个会话一个任务&quot;是硬规则。如果已经有一个任务，直接新建会失败——所以必须先查后建，避免你看到一句莫名其妙的报错。</p><blockquote><p>对你的意义：<strong>创建定时任务时，我可能会先确认一句现有任务的情况</strong>，这是正常流程，不是卡壳。</p></blockquote><h3 id="_28-2-4-什么任务适合定时-什么不适合" tabindex="-1">28.2.4 什么任务适合定时，什么不适合 <a class="header-anchor" href="#_28-2-4-什么任务适合定时-什么不适合" aria-label="Permalink to &quot;28.2.4 什么任务适合定时，什么不适合&quot;">​</a></h3><table tabindex="0"><thead><tr><th>适合 ✅</th><th>不适合 ❌</th></tr></thead><tbody><tr><td>周期性信息汇总</td><td>需要你实时决策的事</td></tr><tr><td>固定格式的报表生成</td><td>依赖临时讨论结论的事</td></tr><tr><td>数据拉取与整理</td><td>一次性的探索任务</td></tr><tr><td>内容排期提醒</td><td>需要人工确认才敢发的动作</td></tr></tbody></table><blockquote><p>判断口诀：<strong>&quot;到点就该做、不用问你、错了也能重来&quot;</strong> —— 三条都满足才适合定时。</p></blockquote><h2 id="_28-3-能力市场-技能、专家、mcp、模板从哪来" tabindex="-1">28.3 能力市场：技能、专家、MCP、模板从哪来 <a class="header-anchor" href="#_28-3-能力市场-技能、专家、mcp、模板从哪来" aria-label="Permalink to &quot;28.3 能力市场：技能、专家、MCP、模板从哪来&quot;">​</a></h2><p>这是本章最&quot;平台化&quot;的部分，也是很多人不知道的入口。</p><p>平台内置了一个<strong>能力市场（Market）</strong>，我可以通过它帮你<strong>搜索和安装</strong>新能力，而不用你自己去翻文档。</p><h3 id="_28-3-1-五个市场" tabindex="-1">28.3.1 五个市场 <a class="header-anchor" href="#_28-3-1-五个市场" aria-label="Permalink to &quot;28.3.1 五个市场&quot;">​</a></h3><table tabindex="0"><thead><tr><th>市场</th><th>你能拿到什么</th></tr></thead><tbody><tr><td>🧭 <strong>专家市场</strong>（assistants）</td><td>各种岗位角色的助手规则</td></tr><tr><td>🛠️ <strong>技能市场</strong>（skills）</td><td>具体能力的技能包</td></tr><tr><td>🔌 <strong>MCP 服务器</strong>（mcp-servers）</td><td>对接外部系统和数据源</td></tr><tr><td>👥 <strong>团队模板</strong>（templates）</td><td>预置的角色组合与工作流</td></tr><tr><td>🤖 <strong>Agent</strong>（agents）</td><td>可直接使用的智能体</td></tr></tbody></table><h3 id="_28-3-2-内容来自哪里" tabindex="-1">28.3.2 内容来自哪里 <a class="header-anchor" href="#_28-3-2-内容来自哪里" aria-label="Permalink to &quot;28.3.2 内容来自哪里&quot;">​</a></h3><p>这些市场不只收平台自产的，而是聚合了多个来源：</p><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td>MomaWork 官方</td><td>平台自研能力</td></tr><tr><td>npm / PyPI</td><td>开发者生态的包</td></tr><tr><td>Smithery</td><td>MCP 服务器生态</td></tr><tr><td>GitHub</td><td>开源项目</td></tr></tbody></table><h3 id="_28-3-3-你能怎么用" tabindex="-1">28.3.3 你能怎么用 <a class="header-anchor" href="#_28-3-3-你能怎么用" aria-label="Permalink to &quot;28.3.3 你能怎么用&quot;">​</a></h3><p><strong>不用说&quot;去市场搜一下&quot;，直接说需求就行：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我需要一个能处理小红书内容的技能，帮我找找并装上</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有没有做财务分析的专家规则？有的话装上</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想接一个数据库 MCP，先给我看看有哪些可选的</span></span></code></pre></div><p><strong>我会做什么</strong>：先搜市场 → 给你几个候选（附说明）→ 你确认后安装 → 装完直接可用。</p><blockquote><p>一条更省事的路径：<strong>先告诉我你的岗位和日常任务</strong>，我可以主动判断你缺什么，一次性把该装的都配齐。</p></blockquote><h2 id="_28-4-webui-把工作台搬到手机和远程" tabindex="-1">28.4 WebUI：把工作台搬到手机和远程 <a class="header-anchor" href="#_28-4-webui-把工作台搬到手机和远程" aria-label="Permalink to &quot;28.4 WebUI：把工作台搬到手机和远程&quot;">​</a></h2><p>默认情况下，我在你电脑上工作。但有些场景你需要<strong>离开电脑还能用</strong>：</p><ul><li>通勤路上突然想让我查个东西</li><li>出差在外需要看昨天生成的报表</li><li>想用平板在会议上展示成果</li><li>团队里其他人也需要访问</li></ul><p><strong>WebUI 模式</strong>解决的就是这个。</p><h3 id="_28-4-1-三种接入方式" tabindex="-1">28.4.1 三种接入方式 <a class="header-anchor" href="#_28-4-1-三种接入方式" aria-label="Permalink to &quot;28.4.1 三种接入方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>适合场景</th><th>特点</th></tr></thead><tbody><tr><td>🏠 <strong>局域网连接</strong></td><td>家里/办公室网络内</td><td>最快，无需额外服务</td></tr><tr><td>🔐 <strong>Tailscale VPN</strong></td><td>在外访问家里的设备</td><td>无需公网 IP，安全性好</td></tr><tr><td>☁️ <strong>服务器部署</strong></td><td>团队共享 / 7×24 在线</td><td>需要服务器与安全配置</td></tr></tbody></table><p><strong>平台支持的系统</strong>：Windows、macOS、Linux、Android。</p><h3 id="_28-4-2-重要原则" tabindex="-1">28.4.2 重要原则 <a class="header-anchor" href="#_28-4-2-重要原则" aria-label="Permalink to &quot;28.4.2 重要原则&quot;">​</a></h3><blockquote><p><strong>所有 WebUI 配置都通过设置界面完成，不要用命令行折腾。</strong></p></blockquote><p>这是刻意设计的：命令行配置容易出错、难以回滚、还容易留下安全缺口。设置界面会帮你处理端口、服务启动、密码等细节。</p><p><strong>常见问题</strong>（我会帮你排查）：端口占用、防火墙拦截、服务没起来、远程访问显示未授权、HTTPS 建议。</p><h3 id="_28-4-3-安全提醒-重要" tabindex="-1">28.4.3 安全提醒（重要） <a class="header-anchor" href="#_28-4-3-安全提醒-重要" aria-label="Permalink to &quot;28.4.3 安全提醒（重要）&quot;">​</a></h3><p>一旦开启远程访问，就等于<strong>把这台机器的操作能力暴露到了网络上</strong>。请务必：</p><table tabindex="0"><thead><tr><th>必须做</th><th>说明</th></tr></thead><tbody><tr><td>设置强密码</td><td>不要用简单密码</td></tr><tr><td>控制访问范围</td><td>优先局域网 / VPN，不要随便暴露公网</td></tr><tr><td>定期检查</td><td>用完就关，或限制客户端数量</td></tr><tr><td>敏感数据隔离</td><td>有商业机密的机器要格外谨慎</td></tr></tbody></table><blockquote><p>一句话：<strong>方便和安全永远要权衡，远程访问的钥匙掌握在你手里。</strong></p></blockquote><h2 id="_28-5-把产出送出去-文件与消息投递" tabindex="-1">28.5 把产出送出去：文件与消息投递 <a class="header-anchor" href="#_28-5-把产出送出去-文件与消息投递" aria-label="Permalink to &quot;28.5 把产出送出去：文件与消息投递&quot;">​</a></h2><p>我生成了文件，但文件躺在你电脑的某个目录里。如果这时候你正拿着手机……</p><p><strong>这就是&quot;投递&quot;类技能的价值。</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>你怎么说</th><th>我做什么</th></tr></thead><tbody><tr><td>把文件发给我</td><td>&quot;把那个文件发给我&quot; / &quot;发给我&quot;</td><td>找到文件并推送给你</td></tr><tr><td>发送图片</td><td>&quot;把刚才那张图发我&quot;</td><td>推送图片</td></tr><tr><td>交付报告</td><td>&quot;生成的报告直接发我微信&quot;</td><td>产出后直接投递</td></tr></tbody></table><p><strong>这个能力看似不起眼，但它补上了自动化链条的最后一环</strong>：定时任务自动生成 → 自动投递给你。全程你都不用坐在电脑前。</p><h2 id="_28-6-接上外部平台" tabindex="-1">28.6 接上外部平台 <a class="header-anchor" href="#_28-6-接上外部平台" aria-label="Permalink to &quot;28.6 接上外部平台&quot;">​</a></h2><p>平台还内置了几个<strong>直连内容平台</strong>的技能，它们和普通&quot;写文案&quot;技能有本质区别——<strong>它们能真的把内容发出去</strong>。</p><h3 id="_28-6-1-内容平台发布-招聘场景" tabindex="-1">28.6.1 内容平台发布（招聘场景） <a class="header-anchor" href="#_28-6-1-内容平台发布-招聘场景" aria-label="Permalink to &quot;28.6.1 内容平台发布（招聘场景）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>平台</th><th>能力</th></tr></thead><tbody><tr><td><code>xiaohongshu-recruiter</code></td><td>小红书</td><td>生成极客风格招聘封面图 + 详情图 + 自动发布流程</td></tr><tr><td><code>x-recruiter</code></td><td>X (x.com)</td><td>文案规范 + 图片生成提示 + 自动发布脚本</td></tr></tbody></table><p><strong>它们的工作方式</strong>（以前者为例）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 你说：发布一个前端工程师的招聘信息到小红书</span></span>
<span class="line"><span>② 我补全：岗位信息、文案、投递方式（没给就用默认的&quot;私信联系&quot;）</span></span>
<span class="line"><span>③ 我出图：自动生成封面图与详情图</span></span>
<span class="line"><span>④ 自动发布：打开浏览器 → 你扫码登录 → 自动填图文 → 一键发布</span></span></code></pre></div><p><strong>注意第 ④ 步</strong>：需要<strong>你扫码登录</strong>。这是刻意的——账号安全永远由你掌握，我只负责流程自动化。</p><h3 id="_28-6-2-招聘以外的用法" tabindex="-1">28.6.2 招聘以外的用法 <a class="header-anchor" href="#_28-6-2-招聘以外的用法" aria-label="Permalink to &quot;28.6.2 招聘以外的用法&quot;">​</a></h3><p>这两个技能的底层能力（<strong>生成视觉素材 + 自动填写发布</strong>）其实可以迁移到任何内容发布场景：</p><ul><li>产品上新图文</li><li>活动宣传帖</li><li>个人 IP 内容分发</li></ul><blockquote><p>思路：<strong>&quot;视觉生成 + 流程自动化&quot;是通用套路，招聘只是它最早被固化的场景。</strong></p></blockquote><h2 id="_28-7-可视化与扩展生态" tabindex="-1">28.7 可视化与扩展生态 <a class="header-anchor" href="#_28-7-可视化与扩展生态" aria-label="Permalink to &quot;28.7 可视化与扩展生态&quot;">​</a></h2><p>平台的能力边界不止内置的那些，还有两层：</p><h3 id="_28-7-1-扩展层" tabindex="-1">28.7.1 扩展层 <a class="header-anchor" href="#_28-7-1-扩展层" aria-label="Permalink to &quot;28.7.1 扩展层&quot;">​</a></h3><p>平台支持<strong>扩展机制</strong>——第三方能力包可以装进来，把你的助手接上外部编辑器、外部工具链。扩展独立升级，不影响平台本体。</p><h3 id="_28-7-2-可视化监控" tabindex="-1">28.7.2 可视化监控 <a class="header-anchor" href="#_28-7-2-可视化监控" aria-label="Permalink to &quot;28.7.2 可视化监控&quot;">​</a></h3><p>工作过程看不到，是很多人对 AI 的抱怨。有一类<strong>配套可视化项目</strong>能解决这个：</p><table tabindex="0"><thead><tr><th>项目</th><th>作用</th></tr></thead><tbody><tr><td>Star Office UI（第三方开源）</td><td>把助手状态（空闲/写作/检索/执行/同步/报错）变成<strong>实时办公室场景</strong>，通过聊天窗口的 TV 图标就能看</td></tr></tbody></table><p><strong>注意</strong>：它不是内置功能，而是一个独立的本地服务。我可以帮你安装、启动、连接和排障（端口、权限、Python 环境等问题）。</p><h3 id="_28-7-3-其他有意思的能力" tabindex="-1">28.7.3 其他有意思的能力 <a class="header-anchor" href="#_28-7-3-其他有意思的能力" aria-label="Permalink to &quot;28.7.3 其他有意思的能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>是什么</th></tr></thead><tbody><tr><td><code>moltbook</code></td><td><strong>AI 代理的社交网络</strong>：可以发帖、评论、点赞、建社区</td></tr><tr><td><code>story-roleplay</code></td><td>角色扮演：解析兼容 SillyTavern 的角色卡（PNG/WebP/JSON），支持关键词触发与动态更新</td></tr><tr><td><code>openclaw-setup</code></td><td>OpenClaw 个人 AI 助手的安装、部署、配置与排障</td></tr><tr><td><code>moma-setup-guide</code></td><td>环境配置向导：按需求从市场挑工具并装好</td></tr></tbody></table><blockquote><p>这一节想传递一个信息：<strong>这个平台的生态是开放的</strong>——官方能力、第三方技能、外部服务、周边可视化都能接进来。</p></blockquote><h2 id="_28-8-组合起来-一条完整的自动产线" tabindex="-1">28.8 组合起来：一条完整的自动产线 <a class="header-anchor" href="#_28-8-组合起来-一条完整的自动产线" aria-label="Permalink to &quot;28.8 组合起来：一条完整的自动产线&quot;">​</a></h2><p>把本章的四件事串起来，你就能得到一条真正的自动化链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 定时任务     每天 18:00 自动启动</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>② 技能         抓取数据 → 生成 Excel 看板</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>③ 专家/模板    内容创作者整理成图文</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>④ 投递         直接发到你微信</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>⑤ WebUI        你在手机上点开就能看</span></span></code></pre></div><p><strong>建议的落地顺序</strong>（不要一次全上）：</p><table tabindex="0"><thead><tr><th>阶段</th><th>先做</th><th>验证标准</th></tr></thead><tbody><tr><td>第 1 步</td><td>先手动跑通整条链路</td><td>人工执行能稳定产出</td></tr><tr><td>第 2 步</td><td>加上定时任务</td><td>连续 3 次按时产出、结果可用</td></tr><tr><td>第 3 步</td><td>加上自动投递</td><td>你不看电脑也能收到</td></tr><tr><td>第 4 步</td><td>再考虑 WebUI / 多端</td><td>确实有离开电脑的需求</td></tr></tbody></table><blockquote><p><strong>先手动跑通，再谈自动化</strong>——这是第 19 章讲过的可靠性原则，在这里同样适用。跳过第 1 步直接上自动化，等于把不确定性放大成事故。</p></blockquote><h2 id="_28-9-本章练习" tabindex="-1">28.9 本章练习 <a class="header-anchor" href="#_28-9-本章练习" aria-label="Permalink to &quot;28.9 本章练习&quot;">​</a></h2><ol><li><strong>建一个定时任务</strong>：挑一件&quot;每周期都要做、不用问你、错了能重来&quot;的事，挂上定时。</li><li><strong>逛一次市场</strong>：写一句你最近的需求（哪怕模糊），让我去市场搜搜看有什么可用。</li><li><strong>打通一次投递</strong>：让某个产出直接投递到你手机上，体验一次&quot;不在电脑前也能收货&quot;。</li><li><strong>画一条你的自动产线</strong>：用 28.8 的模板，写出你业务里最值得自动化的那条链路（只需 4-5 个环节）。</li></ol><hr><blockquote><p>小结：定时任务让我<strong>自己开工</strong>，能力市场让我<strong>持续进化</strong>，投递与平台连接让我<strong>把成果送到你手上</strong>，WebUI 让你<strong>随时随地指挥</strong>。当这四件事组合起来，你拥有的就不再是一个助手，而是一条<strong>会自己运转的产线</strong>——而你，只需要在关键节点做决策。</p></blockquote>`,93)])])}const u=a(d,[["render",n]]);export{b as __pageData,u as default};
